[MODULES] Use these with include <module.scad>:
               1. rounded_cube([width,depth,height], radius, facets)
               // Example: facets = 16; rounded_cube([8, 8, 8], 1, facets);

               2. rounded_cylinder(height, radius, rounding_radius, facets)
               // Example: facets = 16; rounded_cylinder(8, 3, 0.5, facets);

               3. rounded_pyramid(base=[x,y], height, radius, facets)
               // Example: facets = 16; rounded_pyramid([6, 6], 6, 0.5, facets);

               4. rounded_cone(base_radius, height, rounding_radius, facets)
               // Example: facets = 16; rounded_cone(3, 6, 0.5, facets);

               5. gear(number_of_teeth, circular_pitch|diametral_pitch)
               // Example: linear_extrude(1.5) gear(number_of_teeth=8, diametral_pitch=1);

               6. honeycomb(width, depth, cell_size) - 2D shape
               // Example: linear_extrude(1.5) honeycomb(8, 8, 2);

               7. chamfered_cube(size, chamfer)
               // Example: chamfered_cube([6, 6, 6], 0.5);

               8. tube(outer_radius, inner_radius, height, center)
               // Example: tube(3, 1.5, 6, center=true);

               9. torus(major_radius, minor_radius, facets)
               // Example: facets = 16; torus(4, 1, facets);

               10. prism(sides, radius, height, center)
               // Example: prism(6, 3, 6, center=true);

               11. slot(length, width, height, center)
               // Example: slot(10, 3, 2, center=true);

               12. rounded_rectangle(size, radius, center) - 2D shape
               // Example: linear_extrude(2) rounded_rectangle([8, 4], 1, center=true);

               13. fillet_2d(radius, angle) - 2D shape
               // Example: linear_extrude(2) fillet_2d(1.5);

               14. chamfer_2d(size) - 2D shape
               // Example: linear_extrude(2) chamfer_2d(1.5);

               15. text_3d(text, size, height, font, center)
               // Example: text_3d("TEST", 3, 1.5, "Liberation Sans", center=true);

               16. simple_thread(radius, pitch, height, thread_depth, facets)
               // Example: facets = 16; simple_thread(2, 0.8, 6, 0.15, facets);

               17. bearing(outer_radius, inner_radius, height, ball_radius, num_balls)
               // Example: bearing(5, 2, 2, 0.6, 8);

               18. washer(outer_radius, inner_radius, thickness)
               // Example: washer(4, 2, 0.8);

               19. countersunk_hole(hole_radius, head_radius, head_depth, total_depth) - use with difference()
               // Example: difference() { cube([6, 6, 4], center=true); countersunk_hole(1, 2, 1, 4); }

               20. dovetail_male(width, height, depth, angle) & dovetail_female(width, height, depth, angle, clearance)
               // Example: dovetail_male(6, 3, 4, 15); dovetail_female(6, 3, 4, 15, 0.1);

               21. bolt(head_radius, head_height, shaft_radius, shaft_length, thread_pitch)
               // Example: bolt(2.5, 1.5, 1, 8, 0.8);

               22. nut(outer_radius, inner_radius, height, sides, thread_pitch)
               // Example: nut(3, 1, 2, 6, 0.8);

               23. flexible_hinge(length, width, thickness, gap, segments)
               // Example: flexible_hinge(12, 3, 1, 0.15, 6);

               24. lattice(size, cell_size, beam_width)
               // Example: lattice([8, 8, 8], 2, 0.3);

               25. living_hinge(length, width, thickness, cut_width, cut_spacing)
               // Example: living_hinge(15, 4, 0.5, 0.2, 0.8);

               26. spiral(inner_radius, outer_radius, height, turns, facets) - 2D shape
               // Example: facets = 16; linear_extrude(1.5) spiral(1, 4, 1.5, 2, facets);

               27. gear_rack(length, tooth_count, tooth_height, tooth_width)
               // Example: gear_rack(12, 4, 1, 1);

               28. knurling(radius, height, pitch, depth, facets)
               // Example: knurling(2.5, 4, 1, 0.15, 24);

               29. helix(radius, pitch, height, thickness, facets) - complex shape
               // Example: helix(3, 2, 15, 0.3, 16); // Use with caution - can be computationally intensive

               30. spring(radius, wire_radius, pitch, height, facets) - complex shape
               // Example: spring(2.5, 0.4, 2, 12, 16); // Use with caution - can be computationally intensive

               31. Double Helical gears:
                   gear_teeth = 17; gear_pitch = 1; extrude_height = 10; twist_angle = 45; gear_spacing = 50;
                   translate([gear_spacing, 0])
                   {
                      linear_extrude(height = extrude_height, center = true, convexity = 10, twist = -twist_angle)
                      gear(number_of_teeth=gear_teeth, diametral_pitch=gear_pitch);
                      translate([0, 0, extrude_height])
                      rotate([0, 180, 180/gear_teeth])
                      linear_extrude(height = extrude_height, center = true, convexity = 10, twist = twist_angle)
                      gear(number_of_teeth=gear_teeth, diametral_pitch=gear_pitch);
                   }

